"""测试脚手架：临时 SQLite + 随机端口启动真实 HTTP 服务。

后续任务（登录、会话、登出）复用这里的 ``running_server``，保证测试不读写
真实的 ``var/members.db``。
"""

import contextlib
import http.client
import os
import tempfile
import threading

from app.config import load_config
from app.web import create_server


class ServerHandle:
    """包装运行中的测试服务，提供地址与发请求的便捷方法。"""

    def __init__(self, server, config):
        self.server = server
        self.config = config

    @property
    def host(self):
        return self.server.server_address[0]

    @property
    def port(self):
        return self.server.server_address[1]

    @property
    def base_url(self):
        return "http://%s:%d" % (self.host, self.port)

    def request(self, method, path, body=None, headers=None):
        conn = http.client.HTTPConnection(self.host, self.port, timeout=5)
        try:
            conn.request(method, path, body=body, headers=headers or {})
            response = conn.getresponse()
            data = response.read()
            return response.status, dict(response.getheaders()), data
        finally:
            conn.close()


@contextlib.contextmanager
def running_server(extra_env=None):
    """用临时 DB、随机端口启动服务，退出时关闭。"""

    with tempfile.TemporaryDirectory() as tmp:
        env = {
            "PORT": "0",
            "MEMBERS_DB_PATH": os.path.join(tmp, "members.db"),
        }
        if extra_env:
            env.update(extra_env)
        config = load_config(env)
        server = create_server(config)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            yield ServerHandle(server, config)
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=5)

import unittest

from app.config import ConfigError, load_config
from tests import running_server


class ConfigTests(unittest.TestCase):
    def test_default_port_is_8000(self):
        self.assertEqual(load_config({}).port, 8000)

    def test_port_env_override(self):
        self.assertEqual(load_config({"PORT": "18080"}).port, 18080)

    def test_invalid_port_rejected(self):
        for raw in ("abc", "", "0", "65536", "-1"):
            with self.subTest(raw=raw):
                with self.assertRaises(ConfigError):
                    load_config({"PORT": raw})

    def test_default_db_path_and_admin_username(self):
        config = load_config({})
        self.assertEqual(str(config.db_path), "var/members.db")
        self.assertEqual(config.admin_username, "admin")
        self.assertIsNone(config.admin_password)


class HealthTests(unittest.TestCase):
    def test_healthz_returns_200_ok(self):
        with running_server() as handle:
            status, headers, body = handle.request("GET", "/healthz")
        self.assertEqual(status, 200)
        self.assertEqual(body, b"ok")
        self.assertIn("text/plain", headers.get("Content-Type", ""))

    def test_unknown_path_returns_404(self):
        with running_server() as handle:
            status, _, body = handle.request("GET", "/no-such-page")
        self.assertEqual(status, 404)
        self.assertNotIn(b"Traceback", body)


if __name__ == "__main__":
    unittest.main()

